def transform(grid):
    h, w = len(grid), len(grid[0])

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # The repeated singleton markers are the most common non-background color.
    non_bg_counts = {color: count for color, count in counts.items() if color != bg}
    marker = max(non_bg_counts, key=non_bg_counts.get)

    # Find the connected template, excluding its markers.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] in (bg, marker) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x, grid[y][x]))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w
                            and grid[ny][nx] not in (bg, marker)
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append(component)

    template = max(components, key=len)
    anchor_r = (min(r for r, c, v in template) + max(r for r, c, v in template)) // 2
    anchor_c = (min(c for r, c, v in template) + max(c for r, c, v in template)) // 2
    offsets = [(r - anchor_r, c - anchor_c, v) for r, c, v in template]

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for dr, dc, value in offsets:
                    y, x = r + dr, c + dc
                    if 0 <= y < h and 0 <= x < w:
                        out[y][x] = value
    return out
